const resolveChannelAcquisitionAssetCorrelation = `-- name: ResolveChannelAcquisitionAssetCorrelation :many
SELECT effect_id, channel_id, asset_kind, asset_version
FROM channel_acquisition_asset_bindings AS binding
WHERE corp_id = $1::text AND correlation_key = $2::text
  AND (
    (state = 'executed' AND EXISTS (
      SELECT 1 FROM channel_acquisition_asset_attempt_facts AS attempt
      WHERE attempt.effect_id = binding.effect_id AND attempt.state = 'executed'
        AND attempt.completed_at <= $3::timestamptz
    )) OR
    (state = 'reconciled' AND reconcile_resolution = 'provider_applied' AND EXISTS (
      SELECT 1 FROM channel_acquisition_asset_reconciliation_facts AS reconciliation
      WHERE reconciliation.effect_id = binding.effect_id AND reconciliation.resolution = 'provider_applied'
        AND reconciliation.reconciled_at <= $3::timestamptz
    ))
  )
ORDER BY effect_id
LIMIT 2
`

type ResolveChannelAcquisitionAssetCorrelationParams struct {
	CorpID         string             `json:"corp_id"`
	CorrelationKey string             `json:"correlation_key"`
	OccurredAt     pgtype.Timestamptz `json:"occurred_at"`
}

type ResolveChannelAcquisitionAssetCorrelationRow struct {
	EffectID     int64  `json:"effect_id"`
	ChannelID    int64  `json:"channel_id"`
	AssetKind    string `json:"asset_kind"`
	AssetVersion int64  `json:"asset_version"`
}

func (q *Queries) ResolveChannelAcquisitionAssetCorrelation(ctx context.Context, arg ResolveChannelAcquisitionAssetCorrelationParams) ([]ResolveChannelAcquisitionAssetCorrelationRow, error) {
	rows, err := q.db.Query(ctx, resolveChannelAcquisitionAssetCorrelation, arg.CorpID, arg.CorrelationKey, arg.OccurredAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ResolveChannelAcquisitionAssetCorrelationRow{}
	for rows.Next() {
		var i ResolveChannelAcquisitionAssetCorrelationRow
		if err := rows.Scan(
			&i.EffectID,
			&i.ChannelID,
			&i.AssetKind,
			&i.AssetVersion,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

